import json

def _block(title, body):
    if not body:
        return ""
    return "【%s】\n%s\n" % (title, body)

def _speaker(msg):
    role = (msg.get("speaker") or msg.get("role") or "").lower()
    if role in ("consultant", "staff", "agent", "net", "wangzi", "网咨"):
        return "网咨"
    return "客户"

def _fmt_messages(facts):
    lines = []
    for m in facts.get("messages") or []:
        if isinstance(m, dict):
            text = m.get("text") or m.get("content") or ""
            if text:
                lines.append("%s：%s" % (_speaker(m), text))
        elif m:
            lines.append(str(m))
    return "\n".join(lines)

def _fmt_profile(facts):
    mapping = [
        ("emotion", "客户情绪"),
        ("intent", "客户意图"),
        ("portrait", "客户画像"),
        ("ageBand", "年龄段"),
        ("skinTendency", "肤质倾向")
    ]
    lines = []
    for key, label in mapping:
        val = facts.get(key)
        if val:
            lines.append("● %s：%s" % (label, val))
    if not lines and facts:
        return json.dumps(facts, ensure_ascii=False)
    return "\n".join(lines)

def _fmt_items(tool):
    items = tool.get("items") or tool.get("facts") or []
    if not items and tool.get("available") is True:
        return json.dumps(tool, ensure_ascii=False)
    if not items:
        return ""
    chunks = []
    for it in items:
        if not isinstance(it, dict):
            chunks.append(str(it))
            continue
        order = [
            ("name", "名称"), ("certification", "认证"), ("coreEffect", "核心功效"),
            ("brief", "简介"), ("pros", "优点"), ("cons", "缺点"),
            ("duration", "使用/操作时长"), ("effectCycle", "作用周期"),
            ("recovery", "恢复期"), ("interval", "间隔周期"),
            ("anesthesia", "麻醉方式"), ("pain", "疼痛感"),
            ("reversible", "是否可逆"), ("suitable", "适用人群"),
            ("contraindication", "禁忌人群"), ("priceHint", "价格事实")
        ]
        lines = []
        for key, label in order:
            val = it.get(key)
            if val:
                lines.append("%s：%s" % (label, val))
        extra = {k: v for k, v in it.items() if k not in [x[0] for x in order] and v}
        if extra:
            lines.append(json.dumps(extra, ensure_ascii=False))
        chunks.append("\n".join(lines))
    return "\n\n".join(chunks)

def _as_obj(v, default=None):
    if default is None:
        default = {}
    if v is None or v == "":
        return default
    if isinstance(v, (dict, list)):
        return v
    return json.loads(v)

def _merge_item_tools(candidates, details):
    det_items = []
    if isinstance(details, dict):
        det_items = details.get("items") or details.get("facts") or []
    cand_items = []
    if isinstance(candidates, dict):
        cand_items = candidates.get("items") or []
    items = det_items or cand_items
    if not items:
        return {"available": False, "items": []}
    return {"available": True, "items": items}

def main(params):
    parts = []
    if params.get("runMode") == "REGENERATE":
        parts.append(_block("是否换一种生成方向", "换一种回复话术，不要重复上一稿句式。"))

    conv = None
    profile = None
    for b in _as_obj(params.get("factBlocksUsable"), []):
        if b.get("slot") == "conversation":
            conv = b.get("facts") or {}
        if b.get("slot") == "customerProfile":
            profile = b.get("facts") or {}

    if conv:
        body = _fmt_messages(conv)
        if body:
            parts.append(_block("对话上下文", body))
        q = conv.get("currentCustomerQuestion")
        if q:
            parts.append(_block("客户本次提问", q))
    if profile:
        card = _fmt_profile(profile)
        if card:
