def parse_json(value, fallback):
    if value is None or value == '':
        return fallback
    if isinstance(value, (dict, list)):
        return value
    text = str(value).strip()
    if text.startswith('```'):
        text = text.replace('```json', '').replace('```JSON', '').replace('```', '').strip()
    try:
        return json.loads(text)
    except Exception:
        start = text.find('{')
        end = text.rfind('}')
        if start >= 0 and end > start:
            try:
                return json.loads(text[start:end + 1])
            except Exception:
                return fallback
    return fallback

def as_list(value):
    parsed = parse_json(value, [])
    return parsed if isinstance(parsed, list) else []

def clean_text(value):
    return str(value or '').strip()

def clean_score(value):
    try:
        score = float(value)
    except Exception:
        score = 0.0
    return max(0.0, min(1.0, score))

def truthy(value):
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() in ['true', '1', 'yes']

def reason_for_error(error_code):
    reasons = {
        'EMPTY_AUDIO_ID': '缺少音频ID',
        'EMPTY_TRANSCRIPT': '缺少转写文本',
        'EMPTY_CUSTOMERS': '候选客户池为空',
        'NO_VALID_CUSTOMERS': '候选客户池中没有可用客户',
        'MODEL_OUTPUT_PARSE_FAILED': '模型输出不是合法 JSON',
        'NO_IN_POOL_MATCH': '未从候选客户池中识别到足够可信的客户线索',
